        status?:
          | "draft"
          | "pending"
          | "blocked"
          | "needs_attention"
          | "ready"
          | "in_progress"
          | "completed"
          | "failed"
          | "canceled";
        /** @description Filter by task priority */
        priority?: "low" | "medium" | "high" | "urgent";
        /** @description Filter by unread state; false selects read items */
        unread?: boolean;
        /** @description Filter by task title or identifier */
        query?: string;
